<?php
namespace App\Filament\Resources\FoundationSkDocuments\Schemas;
use App\Models\FoundationSkTemplate;use App\Models\User;use App\Models\Employee;use Filament\Forms\Components\FileUpload;use Filament\Forms\Components\Select;use Filament\Forms\Components\TextInput;use Filament\Schemas\Schema;
class FoundationSkDocumentForm { public static function configure(Schema $schema): Schema { return $schema->components([Select::make('user_id')->label('Guru/Pegawai')->options(fn()=>User::query()->whereHas('employee',fn($q)=>$q->where('is_active',true)->whereIn('school_id',auth()->user()?->accessibleSchoolIds() ?? []))->orderBy('name')->pluck('name','id'))->searchable()->preload()->required(),TextInput::make('tahun_sk')->label('Tahun SK')->numeric()->minValue(2000)->maxValue(2200)->required(),Select::make('sk_template_id')->label('Template SK')->options(fn()=>FoundationSkTemplate::query()->where('is_active',true)->orderBy('name')->pluck('name','id'))->required(),FileUpload::make('file')->label('File SK')->storeFiles(false)->acceptedFileTypes(['application/pdf','image/jpeg','image/png'])->maxSize(10240)->required(fn(string $context):bool=>$context==='create')->helperText('PDF/JPG/JPEG/PNG, maksimal 10 MB.')])->columns(2); } }
